import {renderAlbum} from './albums.mjs';
import {initSocial} from './social.mjs';
export function normalizePhone(value){let s=value.replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).replace(/[\s()-]/g,'');if(/^05\d{8}$/.test(s))s='+966'+s.slice(1);else if(/^00/.test(s))s='+'+s.slice(2);if(!/^\+[1-9]\d{7,14}$/.test(s))throw new Error('أدخل رقم جوال صحيحًا، مثل 05xxxxxxxx أو بالصيغة الدولية.');return s}
export function registrationFields(prefix){return `<label>الاسم الرباعي<input id="${prefix}-full" required maxlength="250" autocomplete="name" placeholder="الاسم، الأب، الجد، العائلة"></label><label>رقم الجوال<input id="${prefix}-phone" type="tel" required autocomplete="tel" placeholder="05xxxxxxxx"></label><label>الجنس<select id="${prefix}-gender" required><option value="">اختر…</option><option value="male">ذكر</option><option value="female">أنثى</option></select></label><div id="${prefix}-reference" hidden><label>اسم المعرّف من العائلة (رباعي)<input id="${prefix}-ref" maxlength="250"></label><label>صلة القرابة<select id="${prefix}-relation"><option value="">اختر…</option><option value="father">أب</option><option value="husband">زوج</option><option value="brother">أخ</option><option value="uncle">عم</option><option value="maternal_uncle">خال</option></select></label></div>`}
export function registrationData(prefix='signup'){const val=id=>document.getElementById(prefix+'-'+id).value.trim();const name=val('full').replace(/\s+/g,' '),gender=val('gender');if(name.split(' ').length!==4)throw new Error('أدخل الاسم الرباعي، وتكون العائلة الاسم الأخير.');if(!['male','female'].includes(gender))throw new Error('اختر الجنس.');if(gender==='female'&&(!val('ref')||!val('relation')))throw new Error('أدخل اسم المعرّف وصلة القرابة.');return {sponsor_hint:document.getElementById(prefix+'-sponsor')?.value.trim()||null,display_name:name,full_name:name,phone:normalizePhone(val('phone')),gender,reference_name:gender==='female'?val('ref'):null,relationship:gender==='female'?val('relation'):null}}
export function initCommunity(c){const {$,state,table,req,button,element,toast,busy,start,showSection}=c;
 const rpc=(name,body={})=>req('/rest/v1/rpc/'+name,{method:'POST',body});
 const signup=element('fieldset');signup.id='signup-extra';signup.hidden=true;signup.innerHTML=registrationFields('signup')+'<label>اسم المعرّف أو رقم جواله (اختياري)<input id="signup-sponsor" maxlength="250" placeholder="عضو معتمد يعرفك"></label><p class="muted">إذا فعّل المدير التعريف، يصل طلب موافقة إلى المعرّف المسجل. يمكنك اختيار معرّف من حسابك بعد تأكيد البريد.</p>';$('name-label').after(signup);$('display-name').required=false;
 for(const p of ['signup'])wireReference(p);
 function wireReference(p){$(p+'-gender').onchange=()=>{const female=$(p+'-gender').value==='female';$(p+'-reference').hidden=!female;$(p+'-ref').required=$(p+'-relation').required=female};}
 const profileButton=button('♙ حسابي',openProfile,'secondary');profileButton.id='profile-open';$('logout').before(profileButton);
 function section(id,title,html,admin=false){const tab=button(title,()=>showSection(id));tab.id=id+'-tab';tab.hidden=admin;document.querySelector('.app-nav').append(tab);const box=element('section',undefined,'card');box.id=id+'-section';box.hidden=true;box.innerHTML=html;$('approved').append(box);}
 section('chat','◌ الدردشة',`<h2>دردشة العائلة</h2><p id="chat-status" role="status"></p><div class="chat-layout"><aside><div class="post-actions"><button id="chat-public" class="secondary">♧ الدردشة العامة</button><button id="chat-private" class="secondary">☏ الخاصة</button></div><label>بحث عن عضو<input id="chat-search" placeholder="الاسم الأول أو رقم الجوال…" autocomplete="off"></label><div id="chat-results"></div><h3>محادثاتي</h3><div id="chat-threads"></div></aside><div><h3 id="chat-heading">الدردشة العامة</h3><button id="chat-older" class="text-button" hidden>عرض رسائل أقدم</button><div id="chat-messages" role="log" aria-label="رسائل الدردشة" aria-live="polite"></div><form id="chat-form" class="comment-form"><input id="chat-body" required maxlength="2000" placeholder="اكتب رسالة…" aria-label="الرسالة"><button class="primary">إرسال</button></form></div></div>`);
 section('review','✓ مراجعة الأخبار','<h2>أخبار تنتظر موافقتك</h2><div id="review-list"></div>',true);
 section('settings','⚙ إعدادات العائلة',`<h2>ضوابط العائلة</h2><form id="settings-form"><label class="inline"><input type="checkbox" id="set-chat_enabled"> تشغيل الدردشة</label><label class="inline"><input type="checkbox" id="set-public_chat_enabled"> السماح بالدردشة العامة</label><label class="inline"><input type="checkbox" id="set-private_chat_enabled"> السماح بالدردشة الخاصة</label><label class="inline"><input type="checkbox" id="set-restrict_gender_chat"> منع الدردشة بين الجنسين</label><p class="muted">عند التفعيل: يُخفى الجنس الآخر من بحث الدردشة والمحادثات، وتُفصل رسائل الدردشة العامة حسب الجنس. الحساب الذي لم يحدد جنسه لا يستطيع الدردشة حتى يكمل ملفه.</p><label class="inline"><input type="checkbox" id="set-journalist_approval"> أخبار الصحفي تحتاج موافقة المدير</label><label class="inline"><input type="checkbox" id="set-allow_groups"> السماح للأعضاء بإنشاء مجموعات خاصة</label><label class="inline"><input type="checkbox" id="set-endorsements_enabled"> تفعيل التعريف بالأعضاء وموافقة المعرّف</label><label class="inline"><input type="checkbox" id="set-auto_activate"> اعتماد تلقائي بعد تأكيد البريد ومطابقة العائلة</label><label>أسماء العوائل المسموح بها — عائلة واحدة في كل سطر<textarea id="allowed-families" rows="5" placeholder="أدخل الاسم الأخير من الاسم الرباعي"></textarea></label><p class="muted">المطابقة تعتمد على الاسم المصرّح به وليست إثبات نسب. للنساء: يجب أن يطابق اسم المعرّف عضوًا ذكرًا معتمدًا أكمل اسمه الرباعي؛ وإلا ينتظر الطلب مراجعتك. القائمة الفارغة تبقي الطلبات الجديدة قيد المراجعة.</p><button class="primary">حفظ الإعدادات</button></form>`,true);

 const chatTop=element('div',undefined,'chat-appbar');chatTop.append(element('h2','دردشات العائلة'),button('✕ خروج من الدردشة',()=>showSection('news'),'chat-exit'));$('chat-section').prepend(chatTop);
 const chatLayout=document.querySelector('.chat-layout');chatLayout.classList.add('messenger-layout');
 const conversation=chatLayout.lastElementChild;conversation.classList.add('chat-conversation');
 const roomHead=element('div',undefined,'chat-room-header');const back=button('‹',()=>{chatLayout.classList.remove('has-room');$('chat-search').focus();},'chat-back');back.id='chat-back';back.setAttribute('aria-label','العودة لقائمة المحادثات');
 const roomAvatar=element('span','◌','avatar');roomAvatar.id='chat-room-avatar';roomHead.append(back,roomAvatar,$('chat-heading'));conversation.prepend(roomHead);
 const listTitle=element('div',undefined,'chat-list-heading');listTitle.append(element('h2','الدردشات'),element('small','أفراد العائلة، في مكان واحد'));chatLayout.querySelector('aside').prepend(listTitle);roomHead.append($('group-info'),$('member-info'));
 const publicShortcut=button('',()=>$('chat-public').click(),'chat-contact public-room');publicShortcut.append(element('span','♧','avatar'),element('span','دردشة العائلة العامة'));chatLayout.querySelector('aside').append(publicShortcut);
 const fab=button('',()=>showSection('chat'),'chat-fab');fab.id='chat-fab';fab.hidden=true;fab.setAttribute('aria-label','فتح دردشة العائلة');fab.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11.5a8 8 0 0 1-8 8 8.3 8.3 0 0 1-3.5-.8L4 20l1.3-4.5A8 8 0 1 1 20 11.5Z" fill="none" stroke="currentColor" stroke-width="1.8"/><circle cx="8" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="16" cy="12" r="1"/></svg>';document.body.append(fab);
 let replyMessage=null;const replyBox=element('div',undefined,'chat-reply-preview');replyBox.id='chat-reply-preview';replyBox.hidden=true;$('chat-form').before(replyBox);function clearReply(){replyMessage=null;replyBox.hidden=true;replyBox.replaceChildren();}let roomChanged=true;function enterRoom(){clearReply();chatLayout.classList.add('has-room');roomChanged=true;roomAvatar.textContent=group?'♧':peer?'♙':'◌';if(peer?.avatar_path)social.avatar(peer.avatar_path,roomAvatar);}
 $('chat-section').classList.add('messenger-section');$('chat-section').querySelector(':scope > h2').hidden=true;
 $('chat-body').placeholder='رسالة';$('chat-form').querySelector('button').innerHTML='➤';$('chat-form').querySelector('button').setAttribute('aria-label','إرسال الرسالة');
 const profile=element('dialog');profile.id='profile-dialog';profile.innerHTML=`<div class="feed-heading"><h2>♙ ملفي الشخصي</h2><button id="profile-close" type="button" class="text-button">✕</button></div><p id="profile-email"></p><p id="profile-status"></p><form id="profile-form">${registrationFields('profile')}<button class="primary">حفظ بياناتي</button></form><hr><button id="password-email" class="secondary">✉ تغيير كلمة المرور بتأكيد البريد</button><p class="muted">نرسل رابط تحقق إلى بريدك؛ افتح الرابط لاختيار كلمة المرور الجديدة.</p>`;document.body.append(profile);wireReference('profile');$('profile-close').onclick=()=>profile.close();
 const password=element('dialog');password.id='password-dialog';password.innerHTML='<h2>تعيين كلمة مرور جديدة</h2><p>تم التحقق من رابط البريد. أدخل كلمة المرور الجديدة مرتين.</p><form id="password-form"><label>كلمة المرور الجديدة<input id="new-password" type="password" required minlength="10" autocomplete="new-password"></label><label>تأكيد كلمة المرور<input id="confirm-password" type="password" required minlength="10" autocomplete="new-password"></label><button class="primary">حفظ كلمة المرور</button><button id="password-cancel" type="button" class="secondary">إلغاء</button></form>';document.body.append(password);$('password-cancel').onclick=()=>password.close();
 $('password-form').onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{if($('new-password').value!==$('confirm-password').value)throw new Error('كلمتا المرور غير متطابقتين.');if(!state.recovery)throw new Error('اطلب رابط تأكيد البريد أولًا.');await req('/auth/v1/user',{method:'PUT',body:{password:$('new-password').value}});$('password-form').reset();state.recovery=false;password.close();toast('تم تغيير كلمة المرور.');});};
 $('password-email').onclick=()=>busy($('password-email'),async()=>{await req('/auth/v1/recover?redirect_to='+encodeURIComponent(location.origin+'/'),{method:'POST',auth:false,body:{email:state.user.email}});toast('أرسلنا رابط التحقق إلى بريدك. افتح أحدث رسالة لتغيير كلمة المرور.');});
 async function openProfile(){const p=await rpc('profile_get');$('profile-email').textContent=state.user.email;$('profile-status').textContent=({active:'حساب معتمد',pending:'بانتظار الاعتماد',suspended:'حساب موقوف'}[p.status]);$('profile-full').value=p.full_name||state.profile.display_name;$('profile-phone').value=p.phone||'';$('profile-gender').value=p.gender||'';$('profile-gender').disabled=!!p.gender;$('profile-ref').value=p.reference_name||'';$('profile-relation').value=p.relationship||'';$('profile-gender').onchange();await social.profile(p);profile.showModal();}
 $('profile-form').onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{await rpc('profile_save',{data:registrationData('profile')});profile.close();await start();toast('تم تحديث ملفك.');});};
 let thread=null,peer=null,group=null,cursor=null,searchTimer,searchVersion=0,choosingPrivate=false;
 const social=initSocial(c,{rpc,currentGroup:()=>group?.id,currentPeer:()=>peer,openGroup:async g=>{peer=null;group=g;thread=null;choosingPrivate=false;$('chat-heading').textContent=(g.kind==='event'?'◷ ':'♧ ')+g.title;$('chat-messages').replaceChildren();enterRoom();await loadChat();},clearGroup:async()=>{group=null;thread=null;await loadChat();}});
 document.addEventListener('family:chat',event=>{
  const other=event.detail?.id;if(state.profile?.status!=='active'||!/^[0-9a-f-]{36}$/i.test(other||''))return;
  (async()=>{try{const opened=await rpc('chat_open',{other});const person=await rpc('account_action',{action:'directory_profile',payload:{member:other}});peer=person;group=null;choosingPrivate=false;thread=opened;$('chat-heading').textContent=person.display_name;enterRoom();await showSection('chat');event.detail?.onOpened?.();}catch(e){toast(e.message);}})();
 });

 chatLayout.querySelector('aside').prepend(listTitle);

 const keys=['chat_enabled','public_chat_enabled','private_chat_enabled','restrict_gender_chat','journalist_approval','auto_activate','allow_groups','endorsements_enabled'];
 async function settings(){const rows=await table('family_settings','select=*&id=eq.true');state.settings=rows[0];for(const k of keys)$('set-'+k).checked=!!state.settings[k];const families=await table('allowed_families','select=name&order=name');$('allowed-families').value=families.map(x=>x.name).join('\n');}
 $('settings-form').onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{const names=[...new Set($('allowed-families').value.split('\n').map(x=>x.trim()).filter(Boolean))];if(names.some(n=>n.length<2||n.length>80||/\s/.test(n)))throw new Error('كل عائلة اسم واحد من 2 إلى 80 حرفًا.');const existing=await table('allowed_families','select=name');for(const n of existing)if(!names.includes(n.name))await table('allowed_families','name=eq.'+encodeURIComponent(n.name),{method:'DELETE'});for(const name of names)if(!existing.some(x=>x.name===name))await table('allowed_families','',{method:'POST',body:{name}});await table('family_settings','id=eq.true',{method:'PATCH',body:Object.fromEntries(keys.map(k=>[k,$('set-'+k).checked]))});await settings();toast('تم حفظ ضوابط العائلة.');});};
 async function review(){const rows=await table('posts','select=id,title,body,image_path,image_paths,author_id,profiles:profiles!posts_author_id_fkey(display_name)&moderation_status=eq.pending&deleted_at=is.null&order=created_at.asc&limit=100');const box=$('review-list');box.replaceChildren();for(const p of rows){const card=element('article',undefined,'ad-management');card.append(element('small',p.profiles?.display_name||'صحفي'),element('h3',p.title),element('p',p.body));const album=await renderAlbum(p,c.signedImage);if(album)card.append(album);card.append(button('✓ اعتماد ونشر',async()=>{await table('posts','id=eq.'+p.id,{method:'PATCH',body:{published:true,moderation_status:'published'}});await review();toast('نُشر الخبر.');}),button('رفض النشر',async()=>{await table('posts','id=eq.'+p.id,{method:'PATCH',body:{published:false,moderation_status:'rejected'}});await review();}));box.append(card);}if(!rows.length)box.append(element('p','لا توجد أخبار تنتظر المراجعة.'));}
 async function loadChat(){const rows=await table('family_settings','select=*&id=eq.true');state.settings=rows[0];const s=state.settings,allowed=s.chat_enabled&&(group?true:(thread||choosingPrivate)?s.private_chat_enabled:s.public_chat_enabled);$('chat-form').hidden=!allowed;$('chat-status').textContent=!s.chat_enabled?'الدردشة موقوفة من المدير.':s.restrict_gender_chat?'التواصل متاح لأفراد الجنس نفسه فقط.':'';if(!allowed){$('chat-messages').replaceChildren(element('p','هذه الدردشة موقوفة من المدير.'));$('chat-threads').replaceChildren();$('chat-results').replaceChildren();return;}
 const rooms=await social.loadGroups();if(group)group=rooms.find(g=>g.id===group.id)||group;
 const chats=await rpc('chat_list');$('chat-threads').replaceChildren();for(const t of chats){const row=social.personButton({...t,id:t.member_id},async()=>{peer={id:t.member_id,display_name:t.display_name,avatar_path:t.avatar_path};group=null;choosingPrivate=false;thread=t.id;$('chat-heading').textContent=t.display_name;enterRoom();await loadChat();},'chat-contact');const meta=element('span',undefined,'chat-contact-meta');meta.append(element('strong',t.display_name),element('small',t.last_body||'ابدأ المحادثة'));const picture=row.querySelector('.avatar');row.replaceChildren();if(picture)row.append(picture);row.append(meta);if(t.last_at)row.append(element('time',new Date(t.last_at).toLocaleTimeString('ar-SA',{hour:'2-digit',minute:'2-digit'}),'chat-contact-time'));$('chat-threads').append(row);}
 if(choosingPrivate){$('chat-form').hidden=true;$('chat-messages').replaceChildren();$('chat-older').hidden=true;return;}
 if(group?.kind==='event'&&!group.open_now){$('chat-form').hidden=true;$('chat-messages').replaceChildren(element('p','الدردشة متاحة خلال موعد الحدث فقط.'));return;}
 const messages=group?await rpc('group_action',{action:'read',payload:{id:group.id}}):await rpc('chat_read',{thread,before_id:null});paintMessages(messages,false);cursor=messages[0]?.id;$('chat-older').hidden=messages.length<50;
 }
 function paintMessages(messages,prepend){const box=$('chat-messages'),oldTop=box.scrollTop,near=box.scrollHeight-box.scrollTop-box.clientHeight<90,oldHeight=box.scrollHeight;const fragment=document.createDocumentFragment();let day='';if(!prepend)box.replaceChildren();for(const m of messages){const date=new Date(m.created_at),key=date.toLocaleDateString('ar-SA');if(key!==day){fragment.append(element('div',key,'chat-day'));day=key;}const row=element('article',undefined,'chat-bubble'+(m.sender_id===state.user.id?' mine':''));const pic=button('',()=>social.viewMember({id:m.sender_id}),'avatar');pic.textContent=m.display_name.slice(0,1);pic.setAttribute('aria-label','ملف '+m.display_name);social.avatar(m.avatar_path,pic);if(m.reply_excerpt)row.append(element('blockquote',m.reply_excerpt,'chat-quote'));if(!thread)row.append(pic,element('small',m.display_name,'chat-sender'));row.append(element('p',m.attachment_path&&!m.deleted_at?'مرفق سابق — الدردشة الآن نصية فقط':m.body),element('time',date.toLocaleTimeString('ar-SA',{hour:'2-digit',minute:'2-digit'}),'chat-time'));if(m.edited_at)row.append(element('small','تم التعديل','chat-edited'));if(!m.deleted_at){const more=button('⋮',()=>messageMenu(m),'message-options');more.setAttribute('aria-label','خيارات الرسالة');row.append(more);}fragment.append(row);}if(prepend){box.prepend(fragment);box.scrollTop=oldTop+box.scrollHeight-oldHeight;}else{box.append(fragment);box.scrollTop=(near||roomChanged)?box.scrollHeight:oldTop;roomChanged=false;}}

 function toolsDialog(title){const d=element('dialog');d.append(element('h2',title),button('✕ إغلاق',()=>{d.close();d.remove();},'text-button'));document.body.append(d);d.showModal();return d;}
 function messageMenu(m){const d=toolsDialog('خيارات الرسالة');d.append(button('↩ الرد',()=>{replyMessage=m;replyBox.replaceChildren(element('strong',m.display_name),element('span',m.body.slice(0,250)),button('✕',clearReply));replyBox.hidden=false;d.close();d.remove();$('chat-body').focus();},'secondary'),button('نسخ النص',async()=>{await navigator.clipboard.writeText(m.body);d.close();d.remove();toast('تم نسخ الرسالة.');},'secondary'));if(m.sender_id===state.user.id){if(Date.now()-new Date(m.created_at).getTime()<900000)d.append(button('✎ تعديل',()=>{d.close();d.remove();const edit=toolsDialog('تعديل الرسالة'),text=element('textarea');text.value=m.body;text.maxLength=2000;edit.append(text,button('حفظ التعديل',async()=>{if(!text.value.trim())throw new Error('أدخل نص الرسالة.');await rpc('message_action',{action:'edit',payload:{id:m.id,message:text.value.trim()}});edit.close();edit.remove();await loadChat();},'primary'));},'secondary'));if(Date.now()-new Date(m.created_at).getTime()<172800000)d.append(button('حذف للجميع',async()=>{if(!confirm('حذف رسالتك للجميع؟'))return;await rpc('message_action',{action:'delete',payload:{id:m.id}});d.close();d.remove();await loadChat();},'secondary danger'));}}
 const messageSearch=button('⌕',()=>{const d=toolsDialog('بحث في المحادثة'),search=element('input'),results=element('div');search.type='search';search.placeholder='اكتب كلمة من الرسالة';search.setAttribute('aria-label','البحث في الرسائل');d.append(search,results);let timer,version=0;search.oninput=()=>{clearTimeout(timer);const n=++version;timer=setTimeout(async()=>{try{if(!search.value.trim()){results.replaceChildren();return;}const rows=await rpc('message_action',{action:'search',payload:{thread,group:group?.id||null,term:search.value.trim()}});if(n!==version||!d.open)return;results.replaceChildren();for(const r of rows){const item=element('article',undefined,'activity-row');item.append(element('small',r.display_name+' · '+new Date(r.created_at).toLocaleString('ar-SA')),element('p',r.body));results.append(item);}if(!rows.length)results.append(element('p','لا توجد رسائل مطابقة.'));}catch(e){results.textContent=e.message;}},200);};},'text-button');messageSearch.id='message-search-open';messageSearch.setAttribute('aria-label','البحث في المحادثة');roomHead.append(messageSearch);
 $('chat-older').onclick=()=>busy($('chat-older'),async()=>{const rows=group?await rpc('group_action',{action:'read',payload:{id:group.id,before_id:cursor}}):await rpc('chat_read',{thread,before_id:cursor});paintMessages(rows,true);cursor=rows[0]?.id||cursor;$('chat-older').hidden=rows.length<50;});
 $('chat-public').onclick=()=>busy($('chat-public'),async()=>{peer=null;group=null;choosingPrivate=false;thread=null;$('chat-heading').textContent='دردشة العائلة العامة';enterRoom();await loadChat();});$('chat-private').onclick=()=>busy($('chat-private'),async()=>{chatLayout.classList.remove('has-room');group=null;thread=null;choosingPrivate=true;await loadChat();$('chat-heading').textContent='اختر عضوًا من البحث أو محادثاتك';$('chat-form').hidden=true;$('chat-messages').replaceChildren();$('chat-search').focus();});
 $('chat-search').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>searchMembers().catch(e=>toast(e.message)),350);};
 async function searchMembers(){const request=++searchVersion;const term=$('chat-search').value.trim();if(term.length<1){$('chat-results').replaceChildren();return;}let value=term;try{value=normalizePhone(term);}catch{}const people=await rpc('chat_search',{term:value});if(request!==searchVersion)return;$('chat-results').replaceChildren();for(const p of people)$('chat-results').append(social.personButton(p,async()=>{peer=p;group=null;choosingPrivate=false;thread=await rpc('chat_open',{other:p.id});$('chat-heading').textContent=p.display_name;enterRoom();$('chat-results').replaceChildren();$('chat-search').value='';await loadChat();},'chat-contact'));if(!people.length)$('chat-results').append(element('small','لا توجد نتائج متاحة وفق ضوابط الدردشة.'));}
 $('chat-form').onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{if(replyMessage)await rpc('message_action',{action:'reply_send',payload:{id:replyMessage.id,message:$('chat-body').value.trim()}});else if(group)await rpc('group_action',{action:'send',payload:{id:group.id,message:$('chat-body').value.trim()}});else await rpc('chat_send',{thread,message:$('chat-body').value.trim()});$('chat-body').value='';clearReply();roomChanged=true;await loadChat();});};
 setInterval(()=>{if(!state.user||state.profile?.status!=='active'||$('chat-section').hidden||document.hidden)return;loadChat().catch(e=>{$('chat-messages').replaceChildren();$('chat-form').hidden=true;$('chat-status').textContent=e.message;});},7000);
 return {async load(){const active=state.profile.status==='active';fab.hidden=!active;document.body.classList.toggle('signed-in',true);$('settings-tab').hidden=$('review-tab').hidden=state.profile.role!=='admin'||!active;await social.loaded();if(active){state.settings=(await table('family_settings','select=*&id=eq.true'))[0];}if(state.recovery){password.showModal();}},async show(id){document.body.classList.toggle('chat-page',id==='chat');if(id==='settings'){await settings();await social.settings();}if(id==='review')await review();if(id==='chat')await loadChat();},async memberDetail(member){const d=await rpc('member_detail',{member});return d;},reset(){clearReply();fab.hidden=true;document.body.classList.remove('signed-in','chat-page');chatLayout.classList.remove('has-room');thread=null;group=null;social.reset();$('chat-messages').replaceChildren();$('chat-threads').replaceChildren();$('chat-results').replaceChildren();profile.close();password.close();}};
}
